package generator

import (
	"testing"

	"github.com/google/go-cmp/cmp"
)

func TestRegistration(t *testing.T) {
	_, kinds, header := load(t, "testdata/types/spec.json")
	got, err := Registration(kinds, header)
	if err != nil {
		t.Fatal(err)
	}
	want := string(header) + `
// Code generated by cmd/generator. DO NOT EDIT.

package apis

import (
	"k8s.io/apimachinery/pkg/runtime"

	appsv1alpha1 "github.com/Cliftonz/provider-stripe/apis/apps/v1alpha1"
	corev1alpha1 "github.com/Cliftonz/provider-stripe/apis/core/v1alpha1"
)

func generatedGroups() []func(*runtime.Scheme) error {
	return []func(*runtime.Scheme) error{
		appsv1alpha1.SchemeBuilder.AddToScheme,
		corev1alpha1.SchemeBuilder.AddToScheme,
	}
}
`
	if diff := cmp.Diff(want, string(got)); diff != "" {
		t.Errorf("Registration (-want +got):\n%s", diff)
	}
}
